type View = "dashboard" | "attendance" | "drivers" | "vehicles" | "payroll" | "parties" | "expenses" | "reports";
type ModalType = "driver" | "vehicle" | "party" | "bill" | "invoice" | "expense" | "advance" | "payment" | "quick" | "settings" | null;
type Driver = { id: number; name: string; location: string; salary: number; status: "Active" | "Inactive"; vehicleId: number | null; advance: number; due: number; days: number };
type Vehicle = { id: number; number: string; type: "E-rickshaw" | "Rickshaw"; status: "Running" | "Maintenance" | "Inactive"; partyId: number | null };
type Party = { id: number; name: string; contact: string; rate: number; status: "Active" | "Inactive" };
type Bill = { id: number; no: string; partyId?: number; partyName?: string; partyContact?: string; from: string; to: string; vehicles: number; days: number; rate: number; lineDescription: string; lineAmount: number; advance?: number; total: number; status: "Paid" | "Pending" | "Overdue" };
type Expense = { id: number; date: string; type: "Maintenance" | "Outsourcing" | "Driver misc"; description: string; amount: number; reference: string; direction: "Business cost" | "Driver reimbursement" | "Driver deduction" };
type Payment = { driverId: number; deduction: number; paid: boolean };
type Store = { drivers: Driver[]; vehicles: Vehicle[]; parties: Party[]; bills: Bill[]; expenses: Expense[]; payments: Payment[]; attendance: Record<string, Record<number, boolean>> };

